-- The queries of module `payments`, for the bc-telemetry layout on PostgreSQL.
--
-- Generated by bc-telemetry-gen. Do not edit.
-- Each statement is written for Grafana's PostgreSQL data source: $__timeFilter and
-- $__timeGroupAlias are its macros, expanded to a dashboard's time range and interval.

-- response-bytes: Bytes received from the processor per hour
-- unit: bytes
SELECT $__timeGroupAlias(time, '1h'),
       sum(value) AS value
FROM telemetry."metric__payments__response_size"
WHERE $__timeFilter(time)
GROUP BY 1
ORDER BY 1;

-- settlement-p90: 90th-percentile settlement time per processor over fifteen minutes
-- unit: s
SELECT $__timeGroupAlias(time, '15m'),
       "processor",
       percentile_cont(0.9) WITHIN GROUP (ORDER BY value) AS value
FROM telemetry."metric__payments__settlement_duration"
WHERE $__timeFilter(time)
GROUP BY 1, "processor"
ORDER BY 1;

-- records of log processor_timeout: The processor did not answer in time
SELECT time, body, severity AS level, "processor", "waited"
FROM telemetry."log__payments__processor_timeout"
WHERE $__timeFilter(time)
ORDER BY time DESC;

-- records of error authorization_declined: The processor declined the authorization
SELECT time, body, severity AS level, "order_id", "processor_code"
FROM telemetry."error__payments__authorization_declined"
WHERE $__timeFilter(time)
ORDER BY time DESC;
